package com.novacommerce.order.config;
import com.novacommerce.order.infrastructure.security.CookieBearerTokenResolver; import java.util.*; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.context.annotation.*; import org.springframework.security.authentication.ProviderManager; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.server.resource.authentication.*; import org.springframework.security.oauth2.server.resource.web.authentication.BearerTokenAuthenticationFilter; import org.springframework.security.web.*; import org.springframework.security.web.authentication.*; import org.springframework.security.web.csrf.CookieCsrfTokenRepository; import org.springframework.web.cors.*;
@Configuration public class SecurityConfig {
 @Bean JwtDecoder orderJwtDecoder(OrderProperties p){NimbusJwtDecoder d=NimbusJwtDecoder.withJwkSetUri(p.getAuth().getJwksUri()).build();d.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(p.getAuth().getIssuer()),new AudienceValidator(p.getAuth().getAudience())));return d;}
 @Bean SecurityFilterChain chain(HttpSecurity h,CookieBearerTokenResolver resolver,JwtDecoder decoder,@Qualifier("orderCors")CorsConfigurationSource cors)throws Exception{JwtGrantedAuthoritiesConverter roles=new JwtGrantedAuthoritiesConverter();roles.setAuthoritiesClaimName("roles");roles.setAuthorityPrefix("ROLE_");JwtAuthenticationConverter convert=new JwtAuthenticationConverter();convert.setJwtGrantedAuthoritiesConverter(roles);JwtAuthenticationProvider p=new JwtAuthenticationProvider(decoder);p.setJwtAuthenticationConverter(convert);BearerTokenAuthenticationFilter f=new BearerTokenAuthenticationFilter(new ProviderManager(p),r->{String t=resolver.resolve(r);return t==null?null:new BearerTokenAuthenticationToken(t);});CookieCsrfTokenRepository csrf=CookieCsrfTokenRepository.withHttpOnlyFalse();csrf.setCookieCustomizer(b->b.sameSite("Lax").path("/"));h.csrf(c->c.csrfTokenRepository(csrf)).cors(c->c.configurationSource(cors)).sessionManagement(c->c.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/api/v1/order/csrf").permitAll().requestMatchers("/api/v1/cart/**","/api/v1/checkout","/api/v1/orders/**").hasAnyRole("CUSTOMER","ADMIN").anyRequest().denyAll()).addFilterBefore(f,AnonymousAuthenticationFilter.class).exceptionHandling(e->e.authenticationEntryPoint((q,s,x)->s.sendError(401)).accessDeniedHandler((q,s,x)->s.sendError(403)));return h.build();}
 @Bean(name="orderCors")CorsConfigurationSource cors(OrderProperties p){CorsConfiguration c=new CorsConfiguration();c.setAllowedOrigins(p.getAllowedOrigins());c.setAllowedMethods(List.of("GET","POST","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Content-Type","X-XSRF-TOKEN","Idempotency-Key"));c.setAllowCredentials(true);UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/api/**",c);return s;}
}
